      throws InvalidKeyIdException
  {
    super(context, PREKEY_DIRECTORY, id+"");

    this.structure    = StorageProtos.PreKeyRecordStructure.newBuilder().setId(id).build();
    this.masterSecret = masterSecret;

    loadData();
