public synchronized void setListener(FutureTaskListener<V> listener) {
//    if (listener != null) this.listener = new WeakReference<FutureTaskListener<V>>(listener);
//    else                  this.listener = null;
    this.listener = listener;

    if (this.isDone()) {
      callback();
