      String characters;

      if (type == ALL_TYPE ) characters = emoji.getEmojiUnicode(position);
      else                   characters = emoji.getRecentEmojiUnicode(position);

      int start = composeText.getSelectionStart();
      int end   = composeText.getSelectionEnd  ();

