        final Drawable  bitmap      = getThumbnail(maxWidth, maxHeight);
        final ImageView destination = weakImageView.get();

        if (destination != null && destination.getDrawable() == temporaryDrawable) {
          handler.post(new Runnable() {
            @Override
            public void run() {
