public CharacterState calculateCharacters(int charactersSpent) {
    int maxMessageSize;

    if (charactersSpent <= SmsTransportDetails.SMS_SIZE) {
      maxMessageSize = SmsTransportDetails.SMS_SIZE;
    } else {
      maxMessageSize = SmsTransportDetails.MULTIPART_SMS_SIZE;
    }

    int messagesSpent = charactersSpent / maxMessageSize;

    if (((charactersSpent % maxMessageSize) > 0) || (messagesSpent == 0))
      messagesSpent++;

    int charactersRemaining = (maxMessageSize * messagesSpent) - charactersSpent;

    return new CharacterState(messagesSpent, charactersRemaining, maxMessageSize);
  }

public CharacterState(int messagesSpent, int charactersRemaining, int maxMessageSize) {
      this.messagesSpent       = messagesSpent;
      this.charactersRemaining = charactersRemaining;
      this.maxMessageSize      = maxMessageSize;
    }

private static boolean isWithinWeek(final long millis) {
    return System.currentTimeMillis() - millis <= (WEEK_IN_MILLIS - DAY_IN_MILLIS);
  }

private static boolean isWithinYear(final long millis) {
    return System.currentTimeMillis() - millis <= YEAR_IN_MILLIS;
  }

public static String getBetterRelativeTimeSpanString(final Context c, final long millis) {
    final String prettyDate;
    if (isToday(millis)) {
      prettyDate = DateUtils.formatDateTime(c, millis, DateUtils.FORMAT_SHOW_TIME | DateUtils.FORMAT_ABBREV_TIME);
    } else if (isWithinWeek(millis)) {
      prettyDate = DateUtils.formatDateTime(c, millis,
          DateUtils.FORMAT_SHOW_WEEKDAY | DateUtils.FORMAT_ABBREV_WEEKDAY);
    } else if (isWithinYear(millis)) {
      prettyDate = DateUtils.formatDateTime(c, millis,
          DateUtils.FORMAT_SHOW_DATE | DateUtils.FORMAT_NO_YEAR | DateUtils.FORMAT_ABBREV_ALL);
    } else {
      prettyDate = DateUtils.formatDateTime(c, millis,
          DateUtils.FORMAT_NUMERIC_DATE);
    }
    return prettyDate;
  }

