    try {
      Bitmap bitmap = BitmapFactory.decodeStream(context.getAssets().open("emoji" + File.separator + assetName),
                                                 null, bitmapOptions);

      bitmap = Bitmap.createScaledBitmap(bitmap, 64, 64, true);

      return  new BitmapDrawable(context.getResources(), bitmap);
