private Runnable getWork() {
    synchronized (workQueue) {
      try {
        while (workQueue.isEmpty())
          workQueue.wait();

        return workQueue.remove(0);
      } catch (InterruptedException ie) {
        throw new AssertionError(ie);
      }
    }
  }

